package savannah.model;

import java.util.Iterator;
import java.util.List;

import savannah.config.SimulationConfig;
/**
 * A class representing the shared characteristics between predators
 *
 * @version 25/02/2022
 */
public abstract class Predator extends Animal
{
    // The likelihood of the predator catching its prey
    protected double preyCatchingProbability;

    /**
     * Create a new predator at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected : intial state if the prey is infected or not
     * @param immmune : intial state if the prey is immune or not
     */
    protected Predator(Field field, Location location, boolean randomAge, boolean isInfected, boolean isImmune, SpeciesType speciesType)
    {
        this(field, location, randomAge, isInfected, isImmune, speciesType, SimulationConfig.DEFAULT);
    }

    /**
     * Create a new predator at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected : intial state if the prey is infected or not
     * @param immmune : intial state if the prey is immune or not
     * @param config Shared simulation configuration.
     */
    protected Predator(Field field, Location location, boolean randomAge, boolean isInfected, boolean isImmune, SpeciesType speciesType, SimulationConfig config)
    {
        super(field, location, randomAge, isInfected, isImmune, speciesType, config);
        preyCatchingProbability = speciesType.animalConfig(config).preyCatchingProbability;
    }

    /**
     * @Override
     * 
     * This is what the predators does most of the time - it may move around, it eats prey, 
     * it may breed, it may get infected with a disease, it may become immune to that disease, 
     * it may die of the disease, it may die of hunger, and it may die of old age.
     * 
     * @param newPredators A list to return newly born prey.
     */
    public void act(List<LivingOrganism> newPredators)
    {
        // Predators have a lower chance of acting when its night
        if(Time.isNight()) 
        {
            if (rand.nextDouble() > 0.25)
            {
                return;
            }
        }

        // Predators have a lower chance of acting when its foggy
        if (Weather.getWeather() == Weather.WeatherType.Foggy) 
        {
            if (rand.nextDouble() > 0.50)
            {
                return;
            }
        }

        super.act(newPredators);
    }

    /**
     * @Override
     * 
     * Look for prey adjacent to the current location.
     * Eats prey till full.
     * Predators may catch the prey's disease if eaten.
     * 
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) 
        {
            Location where = it.next();
            Object animal = field.getObjectAt(where, Animal.class);

            if(animal instanceof Prey) 
            {
                Prey prey = (Prey) animal;
                if(prey.isAlive() && foodLevel < maxFoodLevel && rand.nextDouble() < preyCatchingProbability) 
                { 
                    // Predator is hungry and prey is availiable so eat
                    // the prey.
                    int preyFoodValue = prey.beEaten();
                    foodLevel += preyFoodValue;

                    // if the prey being eaten is infected then the predator most likely
                    // gets infected
                    if (prey.getIsInfected() && !getIsImmune() && rand.nextDouble() <= diseaseSpreadProbability)
                    {
                        this.infected = true; 
                    }

                    return where;
                }
            }
        }

        return null;
    }
}

package savannah.app;

import java.awt.Color;

import javax.swing.JButton;

import savannah.config.SimulationConfig;
import savannah.engine.SimulationEngine;
import savannah.model.SpeciesType;
import savannah.model.Time;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing rabbits and foxes.
 *
 * @version 26/02/2022
 */
public class Simulator
{
    private static final SimulationConfig CONFIG = SimulationConfig.DEFAULT;

    // Owns the simulation state.
    private final SimulationEngine engine;
    // A graphical view of the simulation.
    private SimulatorView view;
    // List of buttons that are used to control the simulation.
    private JButton[] buttons;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(CONFIG.defaultDepth, CONFIG.defaultWidth);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = CONFIG.defaultDepth;
            width = CONFIG.defaultWidth;
        }

        engine = new SimulationEngine(depth, width, CONFIG);
        buttons = new JButton[5];

        // Creates the buttons for the view
        JButton playPause = new JButton("Play");
            playPause.addActionListener(e -> new Thread(() -> playPauseButton()).start());
            buttons[0] = playPause;

        JButton runLongSim = new JButton("Run Long Sim");
            runLongSim.addActionListener(e -> new Thread(() -> runLongSimulation()).start());
            buttons[1] = runLongSim;

        JButton simOneStep = new JButton("Sim One Step");
            simOneStep.addActionListener(e -> simulateOneStep());
            buttons[2] = simOneStep;

        JButton reset = new JButton("Reset");
            reset.addActionListener(e -> reset());
            buttons[3] = reset;

        JButton quit = new JButton("Quit");
            quit.addActionListener(e -> quit());
            buttons[4] = quit;

        // Sets the visibility of the buttons in accordance to the current state of the simulation.
        buttonToggle();

        // Create a view of the state of each location in the field.
        view = new SimulatorView(engine.getDepth(), engine.getWidth(), buttons, CONFIG);
        view.setColor(SpeciesType.ZEBRA, Color.BLACK, Color.WHITE);
        view.setColor(SpeciesType.GIRAFFE, Color.YELLOW, Color.BLACK);
        view.setColor(SpeciesType.LEMUR, Color.BLUE, Color.WHITE);
        view.setColor(SpeciesType.LION, Color.RED, Color.WHITE);
        view.setColor(SpeciesType.CHEETAH, Color.ORANGE, Color.BLACK);
        view.setColor(SpeciesType.PLANT, Color.GREEN, Color.BLACK);

        // Setup a valid starting point.
        reset();
    }

    /**
     * Controls the functionality of the Play/Pause button. This depends
     * on whether the simulation is paused or not.
     */
    private void playPauseButton() 
    {
        boolean isPaused = Time.getIsPaused();

        Time.toggleIsPaused();

        if (isPaused) {
            if (! Time.getIsFinished()) {
                simulate();
            }
        }

        buttonToggle();
    }

    /**
     * Run the simulation from its current state for a reasonably long 
     * period: 500 steps.
     */
    private void runLongSimulation()
    {
        simulate(500);
    }

    /**
     * Run the simulation from its current state for the given number of 
     * steps.
     * @param numSteps The number of steps to run for.
     */
    private void simulate(int numSteps)
    {
        // Sets the number of steps that the simulation run started at
        Time.setStepsToRunFor(numSteps);
        simulate();
    }

    /**
     * Run the simulation from its current state for the given number of 
     * steps in the Time Class.
     * Stop before the given number of steps if it ceases to be viable.
     * This is considered to be when only one species remains.
     */
    private void simulate() 
    {
        Time.setIsPaused(false);

        // Adjust button visibility.
        buttonToggle();

        while (! Time.getIsPaused() && ! Time.getIsFinished() && view.isViable(engine.getField())) {
            simulateOneStep();
        }

        Time.setIsPaused(true);
        buttonToggle();
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * predator, prey, and plant.
     */
    private void simulateOneStep()
    {
        engine.step();
        // Show the current state in the view.
        view.showStatus(engine.getField());
    }

    /**
     * Reset the simulation to a starting position.
     */
    private void reset()
    {
        engine.reset();
        buttonToggle();

        // Show the starting state in the view.
        view.showStatus(engine.getField());
    }

    /**
     * Sets the visibility of the buttons in accordance with the current
     * state of the simulation.
     */
    private void buttonToggle() 
    {
        boolean isPaused = Time.getIsPaused();
        boolean isFinished = Time.getIsFinished();

        boolean isStopped = false;
        if (isPaused || isFinished) 
        {
            isStopped = true;
        }

        // Adjust button usability.
        buttons[0].setEnabled(!isFinished);
        buttons[1].setEnabled(isStopped);
        buttons[2].setEnabled(isStopped);
        buttons[3].setEnabled(isStopped);

        // Set the label on the play/pause button.
        if (isStopped) 
        {
            buttons[0].setText("Play");   
        }
        else {
            buttons[0].setText("Pause");
        }
    }

    /**
     * Used by the quit button to close the application.
     */
    private void quit()
    {
        System.exit(0);
    }
}

package savannah.model;

import java.awt.Color;
import java.util.Random;

import savannah.config.SimulationConfig;

/**
 * Enumerates the supported species and their behavior/attribute mappings.
 */
public enum SpeciesType
{
    LION("Lion", Color.RED, Color.WHITE)
    {
        @Override
        public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
        {
            return new Lion(randomAge, field, location, infected, immune, config);
        }
    },
    CHEETAH("Cheetah", Color.ORANGE, Color.BLACK)
    {
        @Override
        public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
        {
            return new Cheetah(randomAge, field, location, infected, immune, config);
        }
    },
    ZEBRA("Zebra", Color.BLACK, Color.WHITE)
    {
        @Override
        public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
        {
            return new Zebra(randomAge, field, location, infected, immune, config);
        }
    },
    GIRAFFE("Giraffe", Color.YELLOW, Color.BLACK)
    {
        @Override
        public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
        {
            return new Giraffe(randomAge, field, location, infected, immune, config);
        }
    },
    LEMUR("Lemur", Color.BLUE, Color.WHITE)
    {
        @Override
        public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
        {
            return new Lemur(randomAge, field, location, infected, immune, config);
        }
    },
    PLANT("Plant", Color.GREEN, Color.BLACK)
    {
        @Override
        public Plant createPlant(boolean randomHealthPercentage, Field field, Location location, SimulationConfig config)
        {
            return new Plant(randomHealthPercentage, field, location, config);
        }
    };

    private final String displayName;
    private final Color fillColor;
    private final Color textColor;

    SpeciesType(String displayName, Color fillColor, Color textColor)
    {
        this.displayName = displayName;
        this.fillColor = fillColor;
        this.textColor = textColor;
    }

    public String getDisplayName()
    {
        return displayName;
    }

    public boolean isPlant()
    {
        return this == PLANT;
    }

    public boolean isAnimal()
    {
        return !isPlant();
    }

    public boolean isPredator()
    {
        return this == LION || this == CHEETAH;
    }

    public boolean isPrey()
    {
        return isAnimal() && !isPredator();
    }

    public Color getFillColor()
    {
        return fillColor;
    }

    public Color getTextColor()
    {
        return textColor;
    }

    public SimulationConfig.SpeciesConfig animalConfig(SimulationConfig config)
    {
        return switch (this) {
            case LION -> config.lion;
            case CHEETAH -> config.cheetah;
            case ZEBRA -> config.zebra;
            case GIRAFFE -> config.giraffe;
            case LEMUR -> config.lemur;
            case PLANT -> throw new IllegalStateException("Plant does not use animal config");
        };
    }

    public SimulationConfig.PlantConfig plantConfig(SimulationConfig config)
    {
        if (!isPlant()) {
            throw new IllegalStateException("Only plant species use plant config");
        }
        return config.plant;
    }

    public int initialAge(boolean randomAge, Random rand, SimulationConfig config)
    {
        if (!isAnimal()) {
            throw new IllegalStateException("Only animal species have ages");
        }

        return randomAge ? rand.nextInt(animalConfig(config).maxAge) : 0;
    }

    public int initialFoodLevel(boolean randomAge, Random rand, SimulationConfig config)
    {
        if (!isAnimal()) {
            throw new IllegalStateException("Only animal species have food levels");
        }

        SimulationConfig.SpeciesConfig speciesConfig = animalConfig(config);
        if (randomAge) {
            return rand.nextInt(speciesConfig.maxFoodLevel);
        }
        if (speciesConfig.useRandomNewbornFoodLevel) {
            double percentageOfMaxFoodLevel = rand.nextDouble() * speciesConfig.randomNewbornFoodLevelMaxFraction;
            return (int) (percentageOfMaxFoodLevel * speciesConfig.maxFoodLevel);
        }
        return (int) (speciesConfig.newbornFoodLevelFraction * speciesConfig.maxFoodLevel);
    }

    public double initialPlantHealth(boolean randomHealth, Random rand, SimulationConfig config)
    {
        if (!isPlant()) {
            throw new IllegalStateException("Only plant species have health");
        }

        SimulationConfig.PlantConfig plantConfig = plantConfig(config);
        if (!randomHealth) {
            return plantConfig.newbornHealthFraction;
        }

        double healthPercentage = rand.nextDouble();
        return Math.max(healthPercentage, plantConfig.minimumRandomHealthFraction);
    }

    public double getPlantSpreadProbability(Weather.WeatherType weather, SimulationConfig config)
    {
        if (!isPlant()) {
            throw new IllegalStateException("Only plant species have spread probabilities");
        }

        return switch (weather) {
            case Sunny -> config.sunnyPlantSpreadProbability;
            case Rainy -> config.rainyPlantSpreadProbability;
            case Foggy -> config.foggyPlantSpreadProbability;
            case Cloudy -> config.cloudyPlantSpreadProbability;
            case Clear -> config.clearPlantSpreadProbability;
        };
    }

    public Animal createAnimal(Field field, Location location, boolean randomAge, boolean infected, boolean immune, SimulationConfig config)
    {
        throw new UnsupportedOperationException(displayName + " is not an animal factory");
    }

    public Plant createPlant(boolean randomHealthPercentage, Field field, Location location, SimulationConfig config)
    {
        throw new UnsupportedOperationException(displayName + " is not a plant factory");
    }
}

